<body>
  <h1>Todos</h1>

  <div class="todo-container">
    <div class="header">
      <input type="text" class="new-todo" placeholder="What needs to be done?" autofocus>
      <button class="add-btn" disabled>Add</button>
    </div>

    <div class="filters">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="active">Active</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>

    <ul class="todo-list"></ul>

    <div class="clear-completed">
      <button>Clear completed</button>
    </div>
  </div>

  <div class="footer">
    <p>Double-click to edit a todo</p>
  </div>

  <script>
    // Initialize from localStorage or empty array
    let todos = JSON.parse(localStorage.getItem('todos')) || [];
    let currentFilter = 'all';

    // DOM elements
    const todoList = document.querySelector('.todo-list');
    const newTodoInput = document.querySelector('.new-todo');
    const addBtn = document.querySelector('.add-btn');
    const filterBtns = document.querySelectorAll('.filter-btn');

    // Render todos
    function renderTodos() {
      todoList.innerHTML = '';

      const filteredTodos = filterTodos(todos);

      filteredTodos.forEach((todo, index) => {
        const li = document.createElement('li');
        li.className = 'todo-item' + (todo.completed ? ' completed' : '');
        li.innerHTML = `
          <label class="toggle" for="todo-${index}"></label>
          <div class="view">
            <label class="label" for="todo-${index}">${escapeHtml(todo.text)}</label>
          </div>
          <button class="destroy" data-index="${index}"></button>
        `;

        // Toggle click
        const toggle = li.querySelector('.toggle');
        toggle.addEventListener('click', (e) => {
          e.stopPropagation();
          toggleTodo(index);
        });

        // Destroy click
        const destroy = li.querySelector('.destroy');
        destroy.addEventListener('click', (e) => {
          e.stopPropagation();
          deleteTodo(index);
        });

        // Double-click to edit
        const label = li.querySelector('.label');
        label.addEventListener('dblclick', () => {
          editTodo(index, label);
        });

        todoList.appendChild(li);
      });

      updateCounter();
      updateAddButtonState();
    }

    // Filter todos
    function filterTodos(todos) {
      if (currentFilter === 'all') return todos;
      if (currentFilter === 'active') return todos.filter(t => !t.completed);
      if (currentFilter === 'completed') return todos.filter(t => t.completed);
      return todos;
    }

    // Toggle todo completion
    function toggleTodo(index) {
      todos[index].completed = !todos[index].completed;
      saveTodos();
      renderTodos();
    }

    // Delete todo
    function deleteTodo(index) {
      todos.splice(index, 1);
      saveTodos();
      renderTodos();
    }

    // Edit todo
    function editTodo(index, labelElement) {
      const input = document.createElement('input');
      input.type = 'text';
      input.value = todoList.dataset.editingTodoIndex ? '' : todo.text;
      input.className = 'edit-input';

      // Place input after label
      labelElement.parentNode.insertBefore(input, labelElement.nextSibling);
      input.focus();

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          const newText = input.value.trim();
          if (newText) {
            todos[index].text = newText;
            saveTodos();
            renderTodos();
          } else {
            deleteTodo(index);
          }
          input.remove();
        } else if (e.key === 'Escape') {
          input.remove();
        }
      });

      input.addEventListener('blur', () => {
        const newText = input.value.trim();
        if (newText) {
          todos[index].text = newText;
          saveTodos();
          renderTodos();
        } else {
          deleteTodo(index);
        }
        input.remove();
      });
    }

    // Save todos to localStorage
    function saveTodos() {
      localStorage.setItem('todos', JSON.stringify(todos));
    }

    // Update counter
    function updateCounter() {
      const activeCount = todos.filter(t => !t.completed).length;
      const counterText = activeCount === 1 ? '1 item left' : `${activeCount} items left`;
      const footer = document.querySelector('.footer');
      if (footer) {
        footer.innerHTML = `<p>${counterText}</p>`;
      }
    }

    // Update add button state
    function updateAddButtonState() {
      addBtn.disabled = newTodoInput.value.trim() === '';
    }

    // Event listeners
    newTodoInput.addEventListener('input', updateAddButtonState);

    addBtn.addEventListener('click', () => {
      const text = newTodoInput.value.trim();
      if (text) {
        todos.push({ text, completed: false });
        newTodoInput.value = '';
        updateAddButtonState();
        saveTodos();
        renderTodos();
      }
    });

    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        currentFilter = btn.dataset.filter;
        renderTodos();
      });
    });

    // Initial render
    renderTodos();
  </script>
</body>
